#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;getline(cin,s);
int cur=0,best=0;
for(char c:s){if(c=='('){++cur;best=max(best,cur);}else if(c==')')--cur;}
printf("%d\n",best);return 0;}

